const pick = (r, ...names) => {
  for (const n of names) {
    if (r && r[n] !== undefined && r[n] !== null && String(r[n]).trim() !== '') return r[n];
  }
  return '';
};
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();

const ADMIN = '6794936273';

const trg = $('Disparador de Telegram').first().json;
const msg = trg.message || {};
const text = String(msg.text == null ? '' : msg.text).trim();
const lower = text.toLowerCase();
const chatId = msg.chat ? String(msg.chat.id) : '';
const nombre = msg.from ? String(msg.from.first_name || '') : '';
const isAdmin = chatId === ADMIN;

// Sesión
let sess = {};
try { sess = $('Leer Sesión').first().json || {}; } catch (e) { sess = {}; }
const paso = sess && sess.Paso ? String(sess.Paso).trim() : '';

// Carrito: { items:[{id,nombre,precio,cantidad}], pending:{id,nombre,precio,stock}|null }
let cart = { items: [], pending: null };
try {
  const raw = sess && sess.Carrito ? JSON.parse(sess.Carrito) : null;
  if (raw && Array.isArray(raw.items)) cart = { items: raw.items, pending: raw.pending || null };
  else if (Array.isArray(raw)) cart = { items: raw, pending: null };
} catch (e) { cart = { items: [], pending: null }; }

// Menú
let menu = [];
try {
  menu = $('Leer Menú').all().map((i) => i.json)
    .filter((r) => r && String(pick(r, 'id_Producto ', 'id_Producto')).trim() !== '');
} catch (e) { menu = []; }

// Categorías disponibles
const cats = [];
for (const r of menu) { const c = String(pick(r, 'Categoria', 'categoria')).trim(); if (c && cats.indexOf(c) === -1) cats.push(c); }

const catAliases = { bebidas: 'Bebidas', bebida: 'Bebidas', comidas: 'Comidas', comida: 'Comidas', almuerzos: 'Comidas', almuerzo: 'Comidas', snacks: 'Snacks', snack: 'Snacks' };
function matchCategoria(t) {
  const n = norm(t);
  for (const c of cats) { if (norm(c) === n) return c; }
  if (catAliases[n]) {
    const target = norm(catAliases[n]);
    for (const c of cats) { if (norm(c) === target) return c; }
  }
  return '';
}

// Routing
let route = 'menu';
let categoriaSel = '';
let estadoPedidoId = '';
let estadoNuevo = '';
let estadoValido = false;
let estadoMensaje = '';

const catTry = matchCategoria(text);

if (lower === '/start' || lower === '/menu' || lower === 'menu' || lower === 'menú' || lower === '/inicio') route = 'menu';
else if (lower === '/carrito' || lower === 'carrito' || lower === 'ver carrito') route = 'carrito';
else if (lower === '/vaciar' || lower === 'vaciar' || lower === 'vaciar carrito') route = 'vaciar';
else if (lower === '/confirmar' || lower === 'confirmar' || lower === 'confirmo') route = 'confirmar';
else if (lower === '/cancelar' || lower === 'cancelar') route = 'vaciar';
else if (lower === '/mispedidos' || lower === 'mis pedidos' || lower === 'mispedidos') route = 'mispedidos';
else if (lower === '/seguir' || lower === 'seguir' || lower === 'seguir comprando') route = 'menu';
else if (lower.startsWith('/reporte')) route = isAdmin ? 'reporte' : 'noauth';
else if (lower.startsWith('/activos')) route = isAdmin ? 'activos' : 'noauth';
else if (lower.startsWith('/estado')) route = isAdmin ? 'estado' : 'noauth';
else if (catTry) { route = 'categoria'; categoriaSel = catTry; }
else if (paso === 'eligiendo') route = 'producto';
else if (paso === 'cantidad') route = 'cantidad';
else route = 'menu';

// Comando admin: /estado ORD-xxxx <Nuevo Estado>
if (route === 'estado') {
  const rest = text.replace(/^\/estado\s*/i, '').trim();
  const m = rest.match(/^(\S+)\s+(.+)$/);
  if (m) {
    estadoPedidoId = m[1].trim();
    estadoNuevo = m[2].trim();
    const permitidos = ['recibido', 'preparación', 'preparacion', 'en camino', 'entregado'];
    estadoValido = permitidos.indexOf(estadoNuevo.toLowerCase()) !== -1;
    const e = estadoNuevo.toLowerCase();
    let extra = '';
    if (e.indexOf('prepar') >= 0) extra = '🍳 Tu pedido está en preparación.';
    else if (e.indexOf('camino') >= 0) extra = '🚚 Tu pedido está en camino.';
    else if (e.indexOf('entreg') >= 0) extra = '✅ Tu pedido ha sido entregado. ¡Buen provecho!';
    else if (e.indexOf('recib') >= 0) extra = '📥 Tu pedido fue recibido.';
    estadoMensaje = '📦 Actualización de tu pedido\n\nPedido: ' + estadoPedidoId + '\n\nNuevo estado:\n' + estadoNuevo + (extra ? ('\n\n' + extra) : '');
  }
}

// Menú principal (categorías)
const emoji = (c) => { const n = norm(c); if (n.indexOf('bebid') >= 0) return '🍺'; if (n.indexOf('comid') >= 0 || n.indexOf('almuerz') >= 0) return '🍽️'; if (n.indexOf('snack') >= 0) return '🍿'; return '•'; };
let menuText = '🍽️ *DeliveryBot - Menú principal*\n\nElige una categoría escribiendo su nombre:\n';
for (const c of cats) { menuText += emoji(c) + ' ' + c + '\n'; }
menuText += '\nOpciones:\n🛒 Ver carrito → escribe *carrito*\n📋 Mis pedidos → escribe *mispedidos*';
if (cart.items && cart.items.length) menuText += '\n\nTienes ' + cart.items.length + ' producto(s) en el carrito. Escribe *confirmar* para finalizar.';

const cartMenuJSON = JSON.stringify({ items: (cart.items || []), pending: null });

return [{
  json: {
    route, text, lower, chatId, nombre, isAdmin, paso, cart,
    cartJSON: JSON.stringify(cart), cartMenuJSON, categoriaSel, menuText,
    estadoPedidoId, estadoNuevo, estadoValido, estadoMensaje, adminId: ADMIN,
  },
}];

const pick = (r, ...names) => { for (const k of names) { if (r && r[k] != null && String(r[k]).trim() !== '') return r[k]; } return ''; };
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const p = $('Preparar').first().json;
const cat = p.categoriaSel;
let menu = [];
try { menu = $('Leer Menú').all().map((i) => i.json); } catch (e) { menu = []; }
const prods = menu.filter((r) => norm(pick(r, 'Categoria', 'categoria')) === norm(cat) && (parseInt(String(pick(r, 'Stock')).replace(/[^0-9-]/g, ''), 10) || 0) > 0);
let mensaje;
if (!prods.length) {
  mensaje = '😔 La categoría *' + cat + '* está temporalmente agotada. Escribe *menu* para volver.';
} else {
  mensaje = '📋 *' + cat + '*\n\n';
  for (const r of prods) {
    const id = String(pick(r, 'id_Producto ', 'id_Producto')).trim();
    const nom = String(pick(r, 'Nombre ', 'Nombre')).trim();
    const desc = String(pick(r, 'Descripcion ', 'Descripcion', 'Descripción')).trim();
    const precio = String(pick(r, 'Precio')).trim();
    const stock = String(pick(r, 'Stock')).trim();
    mensaje += '• *' + id + '* - ' + nom + '\n   ' + desc + '\n   💲$' + precio + ' | stock: ' + stock + '\n';
  }
  mensaje += '\nEscribe el *ID* del producto para agregarlo. O escribe *menu* para volver.';
}
const cartJSON = JSON.stringify({ items: (p.cart && p.cart.items) || [], pending: null });
return [{ json: { chatId: p.chatId, mensaje, cartJSON } }];

const pick = (r, ...names) => { for (const k of names) { if (r && r[k] != null && String(r[k]).trim() !== '') return r[k]; } return ''; };
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const p = $('Preparar').first().json;
const q = norm(p.text);
let menu = [];
try { menu = $('Leer Menú').all().map((i) => i.json); } catch (e) { menu = []; }
const found = menu.find((r) => norm(pick(r, 'id_Producto ', 'id_Producto')) === q || norm(pick(r, 'Nombre ', 'Nombre')) === q);
const items = (p.cart && p.cart.items) || [];
if (!found) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '❌ No encontré ese producto. Escribe el ID tal como aparece, o *menu* para volver.' } }];
}
const id = String(pick(found, 'id_Producto ', 'id_Producto')).trim();
const nombre = String(pick(found, 'Nombre ', 'Nombre')).trim();
const precio = parseFloat(String(pick(found, 'Precio')).replace(/[^0-9.,-]/g, '').replace(/,/g, '')) || 0;
const stock = parseInt(String(pick(found, 'Stock')).replace(/[^0-9-]/g, ''), 10) || 0;
if (stock <= 0) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '😔 ' + nombre + ' está agotado. Escribe *menu* para elegir otro.' } }];
}
const cartJSON = JSON.stringify({ items, pending: { id, nombre, precio, stock } });
return [{ json: { ok: true, chatId: p.chatId, cartJSON, mensaje: '✅ *' + nombre + '* ($' + precio + '). ¿Cuántas unidades? (escribe un número)' } }];

const pick = (r, ...names) => { for (const k of names) { if (r && r[k] != null && String(r[k]).trim() !== '') return r[k]; } return ''; };
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const p = $('Preparar').first().json;
const cart = p.cart || { items: [], pending: null };
const pend = cart.pending;
const qty = parseInt(String(p.text).replace(/[^0-9]/g, ''), 10);
if (!pend || !pend.id) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '⚠️ No hay un producto seleccionado. Escribe *menu* para empezar.' } }];
}
if (isNaN(qty) || qty <= 0) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '🔢 Escribe un número válido de unidades (ej: 2).' } }];
}
let menu = [];
try { menu = $('Leer Menú').all().map((i) => i.json); } catch (e) { menu = []; }
const cur = menu.find((r) => norm(pick(r, 'id_Producto ', 'id_Producto')) === norm(pend.id));
const stock = cur ? (parseInt(String(pick(cur, 'Stock')).replace(/[^0-9-]/g, ''), 10) || 0) : (pend.stock || 0);
const items = Array.isArray(cart.items) ? cart.items.slice() : [];
const existing = items.find((it) => norm(it.id) === norm(pend.id));
const already = existing ? existing.cantidad : 0;
if (qty + already > stock) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '😕 Solo hay ' + stock + ' unidades de ' + pend.nombre + (already ? (' (ya tienes ' + already + ' en el carrito)') : '') + '. Escribe una cantidad menor.' } }];
}
if (existing) existing.cantidad = already + qty;
else items.push({ id: pend.id, nombre: pend.nombre, precio: pend.precio, cantidad: qty });
const cartJSON = JSON.stringify({ items, pending: null });
let total = 0; let resumen = '';
for (const it of items) { const sub = it.precio * it.cantidad; total += sub; resumen += '• ' + it.cantidad + ' x ' + it.nombre + ' = $' + sub + '\n'; }
const mensaje = '🛒 *Tu carrito*\n\n' + resumen + '\n💰 Total: *$' + total + '*\n\nEscribe *confirmar* para finalizar, *carrito* para verlo, una categoría para seguir comprando, o *vaciar*.';
return [{ json: { ok: true, chatId: p.chatId, cartJSON, mensaje } }];

const p = $('Preparar').first().json;
const items = (p.cart && p.cart.items) || [];
if (!items.length) {
  return [{ json: { chatId: p.chatId, mensaje: '🛒 Tu carrito está vacío. Escribe *menu* para ver el menú.' } }];
}
let total = 0; let r = '';
for (const it of items) { const sub = it.precio * it.cantidad; total += sub; r += '• ' + it.cantidad + ' x ' + it.nombre + ' = $' + sub + '\n'; }
const mensaje = '🛒 *Tu carrito*\n\n' + r + '\n💰 Total: *$' + total + '*\n\nEscribe *confirmar*, *vaciar*, o una categoría para seguir comprando.';
return [{ json: { chatId: p.chatId, mensaje } }];

const pick = (r, ...names) => { for (const k of names) { if (r && r[k] != null && String(r[k]).trim() !== '') return r[k]; } return ''; };
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const p = $('Preparar').first().json;
const items = (p.cart && p.cart.items) || [];
if (!items.length) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '🛒 Tu carrito está vacío. Escribe *menu* para pedir.' } }];
}
let menu = [];
try { menu = $('Leer Menú').all().map((i) => i.json); } catch (e) { menu = []; }
// Re-validación de stock (fresco)
const faltantes = [];
for (const it of items) {
  const cur = menu.find((r) => norm(pick(r, 'id_Producto ', 'id_Producto')) === norm(it.id));
  const stock = cur ? (parseInt(String(pick(cur, 'Stock')).replace(/[^0-9-]/g, ''), 10) || 0) : 0;
  if (it.cantidad > stock) faltantes.push(it.nombre + ' (pedido ' + it.cantidad + ', disponible ' + stock + ')');
}
if (faltantes.length) {
  return [{ json: { ok: false, chatId: p.chatId, mensaje: '⚠️ No pude confirmar por falta de stock:\n- ' + faltantes.join('\n- ') + '\n\nEscribe *carrito* para ajustar o *vaciar*.' } }];
}
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const z = (n) => String(n).padStart(2, '0');
const idPedido = 'ORD-' + now.getFullYear() + z(now.getMonth() + 1) + z(now.getDate()) + '-' + z(now.getHours()) + z(now.getMinutes()) + z(now.getSeconds());
const fecha = now.getFullYear() + '-' + z(now.getMonth() + 1) + '-' + z(now.getDate());
const hora = z(now.getHours()) + ':' + z(now.getMinutes()) + ':' + z(now.getSeconds());
let total = 0; const partes = []; const lineas = []; const stockUpdates = [];
for (const it of items) {
  total += it.precio * it.cantidad;
  partes.push(it.cantidad + ' x ' + it.nombre);
  lineas.push('- ' + it.cantidad + ' x ' + it.nombre);
  const cur = menu.find((r) => norm(pick(r, 'id_Producto ', 'id_Producto')) === norm(it.id));
  const stock = cur ? (parseInt(String(pick(cur, 'Stock')).replace(/[^0-9-]/g, ''), 10) || 0) : 0;
  let nuevo = stock - it.cantidad; if (nuevo < 0) nuevo = 0;
  stockUpdates.push({ id: it.id, nombre: it.nombre, nuevoStock: nuevo });
}
const detalles = partes.join(' + ');
const mensajeCliente = '🎉 ¡Pedido confirmado!\n\n📋 Número de pedido: ' + idPedido + '\n💰 Total: $' + total + '\n📦 Estado: Recibido\n\nTe notificaremos cuando cambie el estado de tu pedido.';
const mensajeCocina = '🔔 NUEVO PEDIDO\n\n📋 Orden: ' + idPedido + '\n👤 Cliente: ' + p.nombre + '\n\n🛒 Productos:\n' + lineas.join('\n') + '\n\n💰 Total: $' + total + '\n⏰ ' + fecha + ' ' + hora;
const mensajeAdmin = '🧾 NUEVO PEDIDO (admin)\n\n📋 Orden: ' + idPedido + '\n👤 Usuario: ' + p.nombre + ' (' + p.chatId + ')\n🛒 Productos:\n' + lineas.join('\n') + '\n💰 Total: $' + total + '\n⏰ ' + fecha + ' ' + hora + '\n📦 Estado inicial: Recibido';
return [{ json: { ok: true, chatId: p.chatId, nombre: p.nombre, idPedido, detalles, total: String(total), fecha, hora, stockUpdates, mensajeCliente, mensajeCocina, mensajeAdmin } }];

const p = $('Validar Pedido Final').first().json;
const ups = p.stockUpdates || [];
if (!ups.length) return [];
return ups.map((u) => ({ json: { idProducto: u.id, nombre: u.nombre, nuevoStock: String(u.nuevoStock) } }));

const pick = (r, ...names) => { for (const k of names) { if (r && r[k] != null && String(r[k]).trim() !== '') return r[k]; } return ''; };
const chatId = $('Preparar').first().json.chatId;
let rows = [];
try { rows = $('Leer Mis Pedidos').all().map((i) => i.json).filter((r) => r && String(pick(r, 'id_Pedido', 'id_pedido')).trim() !== ''); } catch (e) { rows = []; }
if (!rows.length) {
  return [{ json: { chatId, mensaje: '📋 Aún no tienes pedidos. ¡Haz tu primer pedido! Escribe *menu*.' } }];
}
rows.sort((a, b) => String(pick(b, 'Fecha ', 'Fecha') + ' ' + pick(b, 'Hora', 'hora')).localeCompare(String(pick(a, 'Fecha ', 'Fecha') + ' ' + pick(a, 'Hora', 'hora'))));
const last = rows.slice(0, 5);
let m = '📋 *Tus últimos pedidos*\n\n';
for (const r of last) {
  m += '• ' + pick(r, 'id_Pedido', 'id_pedido') + '\n   ' + pick(r, 'Fecha ', 'Fecha') + ' | $' + pick(r, 'total_Pago', 'total_pago') + ' | ' + pick(r, 'Estado', 'estado') + '\n';
}
return [{ json: { chatId, mensaje: m } }];

const pick = (r, ...names) => { for (const k of names) { if (r && r[k] != null && String(r[k]).trim() !== '') return r[k]; } return ''; };
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const chatId = $('Preparar').first().json.chatId;
let rows = [];
try { rows = $('Leer Pedidos Activos').all().map((i) => i.json).filter((r) => r && String(pick(r, 'id_Pedido', 'id_pedido')).trim() !== ''); } catch (e) { rows = []; }
const activos = rows.filter((r) => { const e = norm(pick(r, 'Estado', 'estado')); return e !== 'entregado' && e !== 'cancelado'; });
if (!activos.length) {
  return [{ json: { chatId, mensaje: '✅ No hay pedidos activos (todos entregados).' } }];
}
let m = '📦 *Pedidos activos* (' + activos.length + ')\n\n';
for (const r of activos) {
  m += '• ' + pick(r, 'id_Pedido', 'id_pedido') + ' | ' + pick(r, 'Estado', 'estado') + ' | $' + pick(r, 'total_Pago', 'total_pago') + '\n   ' + pick(r, 'Detalles_Pedido', 'detalles_pedido') + '\n';
}
m += '\nPara cambiar un estado: /estado <ID> <Nuevo Estado>';
return [{ json: { chatId, mensaje: m } }];

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const yyyy = now.getFullYear();
const mm = String(now.getMonth() + 1).padStart(2, '0');
const dd = String(now.getDate()).padStart(2, '0');
const today = yyyy + '-' + mm + '-' + dd;

const pick = (r, ...names) => { for (const n of names) { if (r[n] !== undefined && r[n] !== null && String(r[n]).trim() !== '') return r[n]; } return ''; };
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const getId = (r) => pick(r, 'id_Pedido', 'id_pedido');
const getFecha = (r) => pick(r, 'Fecha ', 'Fecha', 'fecha');
const getTotal = (r) => pick(r, 'total_Pago', 'total_pago');
const getDetalle = (r) => pick(r, 'Detalles_Pedido', 'detalles_pedido');
const getHora = (r) => pick(r, 'Hora', 'hora');
const getEstado = (r) => pick(r, 'Estado', 'estado');

const allRows = $input.all().map((i) => i.json).filter((r) => r && String(getId(r)).trim() !== '');
const todayRows = allRows.filter((r) => String(getFecha(r) || '').trim().slice(0, 10) === today);

if (todayRows.length === 0) {
  return [{ json: { hasSales: false, mensaje: '📊 REPORTE DIARIO DELIVERYBOT — ' + today + '\n\nHoy no se registraron ventas.' } }];
}

let total = 0;
for (const r of todayRows) {
  const v = parseFloat(String(getTotal(r)).replace(/[^0-9.,-]/g, '').replace(/,/g, ''));
  if (!isNaN(v)) total += v;
}

const counts = {};
for (const r of todayRows) {
  const detalle = String(getDetalle(r) || '');
  const parts = detalle.split(/[+,;]/);
  for (const part of parts) {
    const m = part.trim().match(/^(\d+)?\s*(?:x\s*)?(.+)$/i);
    if (m) {
      const qty = m[1] ? parseInt(m[1], 10) : 1;
      const nombre = m[2].trim().toLowerCase();
      if (nombre) counts[nombre] = (counts[nombre] || 0) + (isNaN(qty) ? 1 : qty);
    }
  }
}
let estrella = 'N/D';
let estrellaQty = 0;
for (const k of Object.keys(counts)) { if (counts[k] > estrellaQty) { estrellaQty = counts[k]; estrella = k; } }
if (estrella !== 'N/D') estrella = estrella.charAt(0).toUpperCase() + estrella.slice(1);

const hourCounts = {};
for (const r of todayRows) { const h = String(getHora(r) || '').trim().slice(0, 2); if (h) hourCounts[h] = (hourCounts[h] || 0) + 1; }
let horaPico = 'N/D';
let horaPicoCount = 0;
for (const h of Object.keys(hourCounts)) { if (hourCounts[h] > horaPicoCount) { horaPicoCount = hourCounts[h]; horaPico = h + ':00'; } }

// Pedidos por estado
const est = { recibido: 0, 'preparación': 0, 'en camino': 0, entregado: 0 };
for (const r of todayRows) {
  const e = norm(getEstado(r));
  if (e.indexOf('prepar') >= 0) est['preparación']++;
  else if (e.indexOf('camino') >= 0) est['en camino']++;
  else if (e.indexOf('entreg') >= 0) est.entregado++;
  else est.recibido++;
}

const mensaje =
  '📊 REPORTE DIARIO DELIVERYBOT — ' + today + '\n\n' +
  '📦 Pedidos realizados: ' + todayRows.length + '\n' +
  '💰 Total vendido: $' + total.toFixed(0) + '\n\n' +
  '🏆 Producto más vendido:\n' + estrella + (estrellaQty ? ' - ' + estrellaQty + ' unidades' : '') + '\n\n' +
  '⏰ Hora pico:\n' + horaPico + (horaPicoCount ? ' (' + horaPicoCount + ' pedidos)' : '') + '\n\n' +
  '📋 Estados:\nRecibidos: ' + est.recibido + '\nEn preparación: ' + est['preparación'] + '\nEn camino: ' + est['en camino'] + '\nEntregados: ' + est.entregado;

return [{ json: { hasSales: true, mensaje } }];
